  supportedTopLevelFiles: string[];
  insightPacketFiles: string[];
  ignoredMetadataPathSegments: string[];
  ignoredWorkspaceBundlePathSegments: string[];
  metadataSegmentRules: Array<{
    segment: string;
    suffixes: string[];
  }>;
  objectMetadataSuffixes: string[];
  excludedWorkspaceSegments: string[];
